SECTIONS = [
    ('forms', '🤔 Понять, какой вариант мне подходит'),
    ('prepare', '✅ Начать оформление'),
    ('find', '👶 Найти ребёнка'),
    ('chosen', '❤️ Я уже выбрал ребёнка'),
    ('home', '🏠 Ребёнок уже в моей семье'),
    ('next', '🧭 Я уже начал — найти мой следующий шаг'),
]

STAGES = [('Ещё выбираю форму', 'fq_section_forms'), ('Нужна ШПР', 'fq_training'),
          ('Прохожу медосмотр', 'fq_medical'), ('Собираю документы', 'fq_documents'),
          ('Подаю заявление / жду обследование', 'fq_application'),
          ('Есть заключение — ищу ребёнка', 'fq_section_find'),
          ('Нашёл ребёнка / получил направление', 'fq_meeting'),
          ('Решил усыновить', 'fq_court'), ('Решил оформить опеку', 'fq_appoint'),
          ('Хочу оформить приёмную семью', 'fq_foster_setup'),
          ('Ребёнок уже со мной', 'fq_section_home')]


def configure(config):
    c = deepcopy(config)
    nodes = {n['id']: n for n in c['nodes']}
    added = {}
    for key, (title, url) in SOURCES.items():
        c['sources']['fq_' + key] = dict(title=title, url=url, checked='2026-09-24')

    def node(key, title, text, parent=None, choices=(), sources=(), tasks=()):
        controls = [dict(label=label, target=target) for label, target in choices]
        controls += [dict(label=SOURCES[s][0], url=SOURCES[s][1]) for s in sources]
        if tasks:
            controls.append(dict(label='Отметить выполненное', target='checklist'))
        if parent:
            controls.append(dict(label='Назад', target=parent))
            if parent != 'family':
                controls.append(dict(label='К разделу семьи', target='family'))
        controls.append(dict(label='На главную', target=c['menu']))
        if parent and not choices:
            controls.append(dict(label='Напомнить', target='reminder_new',
                                 values={'reminder_text': 'Вернуться к памятке.'}))
        added[key] = dict(id=key, title=title, branch='family', kind='message', text=text,
                         adult_text=text, buttons=controls, next='', tasks=list(tasks), routes=[],
                         conditions=[], sources=[], content_status='prepared', editorial_parent=parent,
                         editorial_sources=['fq_' + s for s in sources])

    node('family', 'Хочу принять ребёнка в семью',
         'ХОЧУ ПРИНЯТЬ РЕБЁНКА В СЕМЬЮ\n\nЧто вам сейчас нужно? Можно начать с выбора формы, '
         'подготовки документов или того этапа, на котором вы уже находитесь.\n\n'
         'Здесь собраны готовые памятки для устройства ребёнка в России. Это не полный список. '
         'Местные выплаты и льготы зависят от региона.',
         choices=[(title, 'fq_section_' + key) for key, title in SECTIONS])
    for key, title in SECTIONS:
        choices = STAGES if key == 'next' else [(t[2], 'fq_' + t[0]) for t in TOPICS if t[1] == key]
        node('fq_section_' + key, title, title + '\n\nВыберите подходящий вопрос или этап.', 'family', choices)
    for key, section, title, intro, questions in TOPICS:
        node('fq_' + key, title, title + '\n\n' + intro, 'fq_section_' + section,
             [(q[1], 'fq_' + key + '_' + q[0]) for q in questions])
        for suffix, label, answer, sources, tasks in questions:
            node('fq_' + key + '_' + suffix, label, label + '\n\n' + answer,
                 'fq_' + key, sources=sources, tasks=tasks)

    aliases = {'forms': 'fq_section_forms', 'forms_extra': 'fq_section_forms',
               'docs_family': 'fq_section_prepare', 'family_steps': 'fq_section_prepare',
               'adoption': 'fq_documents_adopt', 'adoption_extra': 'fq_adoption',
               'guardianship': 'fq_documents_guardian', 'guardianship_extra': 'fq_guardian',
               'foster': 'fq_foster_setup', 'foster_extra': 'fq_foster',
               'child_documents': 'fq_section_home', 'child_documents_extra': 'fq_section_home',
               'children': 'fq_section_find'}
    for old, target in aliases.items():
        if old in nodes:
            alias = deepcopy(added[target])
            alias['id'] = old
            nodes[old] = alias
    nodes.update(added)
    c['nodes'] = list(nodes.values())
    for branch in c['branches']:
        if branch['id'] == 'family':
            branch.update(title='Родителям — принятие ребёнка в семью', entry='family',
                          roles=['parent', 'candidate'], status='draft')
    material_id = 'family_prepared_questions'
    c['materials'] = [m for m in c['materials'] if m['id'] != material_id]
    c['materials'].append(dict(
        id=material_id, title='Родителям: шесть входов и готовые ответы',
        text='Подготовлено по исследованиям (12), (13) и схеме владельца; проверено 24.09.2026. '
             'Нет поиска организаций, региональных вычислений или LLM-консультации. '
             'Ссылки на нормы подписаны как материалы, не как электронные заявления. '
             'Исправлена ошибка исследования о согласии ребёнка 10+ на назначение опекуна.\n\n' +
             '\n\n'.join(n['text'] + ('\n' + '\n'.join(n['tasks']) if n['tasks'] else '') for n in added.values()),
        branches=['family'], roles=['parent', 'candidate'], regions=[], min_age=None, max_age=None,
        sources=['fq_' + k for k in SOURCES], checked='2026-09-24', review_days=30, enabled=False))
    return validate(c), added


def main():
    before = request('state')
    config, added = configure(before['config'])
    out = ROOT / 'docs/test-results/family-questions'
    out.mkdir(parents=True, exist_ok=True)
    (out / 'before.json').write_text(json.dumps(before['config'], ensure_ascii=False, indent=2), encoding='utf-8')
    saved = request('draft', dict(config=config, revision=before['revision']), 'PUT')
    after = request('state')
    assert after['config'] == config and after['revision'] == saved['revision']
    assert after['published_id'] == before['published_id']
    result = dict(revision_before=before['revision'], revision=after['revision'],
                  published_id=after['published_id'], topics=len(TOPICS), screens=len(added),
                  questions=sum(len(t[4]) for t in TOPICS), source_count=len(SOURCES))
    (out / 'update.json').write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding='utf-8')
    copy = '# Родителям: реплики черновика\n\n'
    for n in added.values():
        copy += '## ' + n['title'] + '\n\n' + n['text'] + '\n\n'
        copy += ''.join('- [ ] ' + task + '\n' for task in n['tasks'])
        copy += '\nКнопки: ' + ', '.join(b['label'] for b in n['buttons']) + '\n\n'
        copy += ''.join('- [' + b['label'] + '](' + b['url'] + ')\n' for b in n['buttons'] if 'url' in b) + '\n'
    (ROOT / 'docs/family-question-copy.md').write_text(copy, encoding='utf-8')
    print(json.dumps(result))


if __name__ == '__main__':
    main()
